$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot '..' 'ExportHardwareInventory.psm1') -Force
function Assert-Equal($Expected,$Actual,[string]$Message){if($Expected-ne$Actual){throw "$Message Expected '$Expected', got '$Actual'."}}
$offsets=[Collections.Generic.List[int]]::new();$fetchPage={param($offset,$size)$offsets.Add([int]$offset);if($offset-eq 0){[pscustomobject]@{pageSize=2;total=3;devices=@([pscustomobject]@{network='Default';ipAddress='192.0.2.1';hostname='one';adapterId='Cisco::IOS'},[pscustomobject]@{network='Lab';ipAddress='192.0.2.2';hostname='two'})}}else{[pscustomobject]@{pageSize=2;total=0;devices=@([pscustomobject]@{network='Lab';ipAddress='192.0.2.3';hostname='three'})}}};$fetchHardware={param($device)if($device.ipAddress-eq'192.0.2.2'){throw'simulated lookup failure'};if($device.ipAddress-eq'192.0.2.3'){return @()};@([pscustomobject]@{hardwareId=7;assetType='CHASSIS';make='Acme';latest=$true;cardParentId=-1})};$devices=@(Get-NetLDInventoryDevices $fetchPage 2);Assert-Equal 3 $devices.Count 'Device count';Assert-Equal '0,2' ($offsets-join',') 'Offsets';$base=Join-Path ([IO.Path]::GetTempPath()) "netld-hardware-$([guid]::NewGuid())";try{$csv=Join-Path $base 'hardware.csv';$json=Join-Path $base 'hardware.json';$failure=Join-Path $base 'failures.csv';$result=Export-NetLDHardwareData $devices $fetchHardware $csv $failure csv;Assert-Equal 1 $result.HardwareCount 'Hardware count';Assert-Equal 1 $result.FailureCount 'Failure count';Assert-Equal 'CHASSIS' @(Import-Csv $csv)[0].assetType 'CSV asset';Export-NetLDHardwareData $devices $fetchHardware $json $failure json|Out-Null;$rows=Get-Content $json -Raw|ConvertFrom-Json;Assert-Equal $true @($rows)[0].latest 'JSON boolean'}finally{Remove-Item $base -Recurse -Force -ErrorAction SilentlyContinue};Write-Host 'PowerShell hardware export tests passed.'
